<?php require '_init.php';$pageTitle='Brands & categories';$errors=[];if(post()){verify_csrf();$table=textval('type')==='category'?'categories':'brands';$fk=$table==='brands'?'brand_id':'category_id';$name=textval('name');$id=number('id');$action=textval('action');try{if($action==='delete'){query('DELETE FROM '.$table.' WHERE id=?',[$id]);flash('Removed.');redirect('admin/taxonomy.php');}else{if(mb_strlen($name)<2||mb_strlen($name)>80)$errors[]='Name must be 2–80 characters.';if(!$errors){if($id)query('UPDATE '.$table.' SET name=? WHERE id=?',[$name,$id]);else query('INSERT INTO '.$table.'(name) VALUES (?)',[$name]);flash('Saved.');redirect('admin/taxonomy.php');}}}catch(PDOException $e){if($e->getCode()!=='23000')throw $e;$errors[]='Name already exists, or this item is still used by a product (including archived products).';}}require '../includes/header.php';?><section class="container section"><h1>Brands & categories</h1><?php errors($errors);?><div class="contact-grid"><?php foreach(['brand'=>'Brands','category'=>'Categories'] as $type=>$label):$table=$type==='brand'?'brands':'categories';?><div class="panel"><h2><?=$label?></h2><form method="post" class="inline-form"><?php csrf();?><input type="hidden" name="type" value="<?=$type?>"><label>New <?=e($type)?><input name="name" minlength="2" maxlength="80" required></label><button>Add</button></form><?php foreach(query('SELECT * FROM '.$table.' ORDER BY name')->fetchAll() as $item):?><form method="post" class="inline-form taxonomy"><?php csrf();?><input type="hidden" name="type" value="<?=$type?>"><input type="hidden" name="id" value="<?=$item['id']?>"><label class="sr-only" for="<?=$type.$item['id']?>">Name</label><input id="<?=$type.$item['id']?>" name="name" value="<?=e($item['name'])?>" minlength="2" maxlength="80" required><button name="action" value="save" class="outline">Save</button><button name="action" value="delete" class="link" formnovalidate>Delete</button></form><?php endforeach;?></div><?php endforeach;?></div></section><?php require '../includes/footer.php';?>
